#![allow(unused_imports)]
verus! {
    // We need Vec from pervasive
    use pervasive::vec::Vec;

    /// Given an input vector `a`, produce a new vector `z` of the same length,
    /// filled entirely with zeros.
    /// 
    /// Guarantees:
    /// 1) z.len() == a.len()
    /// 2) For all i < a.len(): z[i] == 0
    /// 3) For any other vector b of the same length,
    ///    adding z on either side leaves b unchanged:
    ///      ∀i. b[i] + z[i] == b[i]
    ///      ∀i. z[i] + b[i] == b[i]
    fn zeros_like(a: &Vec<i32>) -> Vec<i32>
        ensures
            |z: &Vec<i32>| z.len() == a.len() &&
            forall|i: usize| i < a.len() ==> z[i] == 0 &&
            forall|b: &Vec<i32>| b.len() == a.len() ==>
                (forall|i: usize| i < a.len() ==> b[i] + z[i] == b[i]) &&
            forall|b: &Vec<i32>| b.len() == a.len() ==>
                (forall|i: usize| i < a.len() ==> z[i] + b[i] == b[i])
    {
        // Pre-allocate exactly a.len() slots
        let mut z = Vec::with_capacity(a.len());
        let mut i: usize = 0;

        // Build up z one zero at a time
        while i < a.len()
            invariant i <= a.len()
            invariant z.len() == i
            invariant forall|j: usize| j < i ==> z[j] == 0
            decreases a.len() - i
        {
            z.push(0);
            i += 1;
        }

        z
    }

    proof fn test_zeros_like() {
        let a = Vec::from_slice(&[5, -3, 42]);
        let z = zeros_like(&a);
        // Check the basic properties
        assert(z.len() == a.len());
        assert(forall|i: usize| i < a.len() ==> z[i] == 0);

        // Check that b + z == b
        let b = Vec::from_slice(&[10, 20, 30]);
        assert(forall|i: usize| i < b.len() ==> b[i] + z[i] == b[i]);
        assert(forall|i: usize| i < b.len() ==> z[i] + b[i] == b[i]);
    }
}